import re

import six


def check_timestring(*args):
    """
    Check that timestrings given as arguments are robot compatible timestrings
    Raises ValueError for incompatible values
    :param args: timestrings to be checked
    :return:
    """
    for timestr in args:
        if timestr:
            _verify_that_timestr_dont_have_more_than_2_colons(timestr)
            timestr_to_secs(timestr)


def _verify_that_timestr_dont_have_more_than_2_colons(timestr):
    """
    Only two colons are permitted inside timestring/datestring: between seconds-minutes and minutes-hours,
    eg: good: 10:10:10     #h:m:s
        bad:  10:10:10:10  #h:m:s:<ignored>
    """
    if len(re.findall(':', timestr)) > 2:
        raise ValueError


def convert_timestring(timestr):
    """
    Convert robot compatible timestrings to seconds in float
    Raises ValueError for incompatible values
    :param args: timestrings to be checked
    :return:
    """
    if timestr.lower() == 'forever':
        timestr = '9999 days'
    _verify_that_timestr_dont_have_more_than_2_colons(timestr)
    return timestr_to_secs(timestr)


def force_list(value):
    """
    Returns a list from given value, if value is not a list
    :param value: value to be checked and converted to list if needed
    :return: List
    """
    if value is None:
        return []
    elif not isinstance(value, list):
        return [value]
    return value


_timer_re = re.compile(r'([+-])?(\d+:)?(\d+):(\d+)(.\d+)?')
tput_uservalue_pattern = re.compile(r'^([\d.]+) {0,1}([kmg]{0,1}(bits|bytes)/sec)')
_WHITESPACE_REGEXP = re.compile(r'\s+')


def tput_user_value2normalized(user_value, direction=''):
    """
    Returns throughput in Kbits/seconds unit
    Perform conversion from following units:
    - 'bits/sec'
    - 'Kbits/sec'           1 000 bits/sec
    - 'Mbits/sec'       1 000 000 bits/sec
    - 'Gbits/sec'   1 000 000 000 bits/sec
    - 'Bytes/sec'               8 bits/sec
    - 'KBytes/sec'          1 000 Bytes/sec
    - 'MBytes/sec'      1 000 000 Bytes/sec
    - 'GBytes/sec'  1 000 000 000 Bytes/sec
    eg. '100 MBytes/sec' == '800000 Kbits/sec'

    :param user_value: throughput as string in user readable format
    :return: throughput in Kbits/seconds unit
    """
    if isinstance(user_value, six.string_types):
        user_value = user_value.lower()
    found_object = tput_uservalue_pattern.search(user_value)
    if found_object is None:
        raise ValueError(f"Invalid {direction} throughput string: '{user_value}'\n{tput_user_value2normalized.__doc__}")
    convertion_rate = {
        'bits/sec': 0.001,
        'kbits/sec': 1.,
        'mbits/sec': 1000.,
        'gbits/sec': 1000000.,
        'bytes/sec': 0.008,
        'kbytes/sec': 8 * 1.,
        'mbytes/sec': 8 * 1000.,
        'gbytes/sec': 8 * 1000000.,
    }

    value, unit = found_object.group(1), found_object.group(2)
    convert_value = convertion_rate[unit] * float(value)
    return round(convert_value, 4)


def timestr_to_secs(timestr, round_to=3):
    """
    Parses time like '1h 10s', '01:00:10' or '42' and returns seconds.

    :param timestr: robot timestring
    :param round_to: decimal of seconds to be returned
    :return: time as seconds
    """
    if isinstance(timestr, six.string_types):
        for converter in _timer_to_secs, _time_string_to_secs:
            secs = converter(timestr)
            if secs is not None:
                return secs if round_to is None else round(secs, round_to)
    raise ValueError(f"Invalid time string: '{timestr}'.")


def _parse_time_string_characters(timestr):
    time_data = {'millis': 0, 'secs': 0, 'mins': 0, 'hours': 0, 'days': 0}
    destination = {'x': 'millis', 's': 'secs', 'm': 'mins', 'h': 'hours', 'd': 'days'}
    temp = []
    for c in timestr:
        try:
            if c in destination.keys():
                time_part = destination[c]
                time_data[time_part] = float(''.join(temp))
                temp = []
                continue
            temp.append(c)
            # Original
            # if   c == 'x': millis = float(''.join(temp)); temp = []
            # elif c == 's': secs   = float(''.join(temp)); temp = []
            # elif c == 'm': mins   = float(''.join(temp)); temp = []
            # elif c == 'h': hours  = float(''.join(temp)); temp = []
            # elif c == 'd': days   = float(''.join(temp)); temp = []
            # else: temp.append(c)
        except ValueError:
            return None
    if temp:
        return None
    return time_data


def _time_string_to_secs(timestr):
    timestr = _normalize_timestr(timestr)
    if not timestr:
        return None
    sign = 1
    if timestr[0] == '-':
        sign = -1
        timestr = timestr[1:]
    time_data = _parse_time_string_characters(timestr)
    if time_data:
        millis = time_data['millis']
        secs = time_data['secs']
        mins = time_data['mins']
        hours = time_data['hours']
        days = time_data['days']
        return sign * (millis / 1000 + secs + mins * 60 + hours * 60 * 60 + days * 60 * 60 * 24)
    return None


def _timer_to_secs(number):
    match = _timer_re.match(number)
    if not match:
        return None
    prefix, hours, minutes, seconds, millis = match.groups()
    seconds = float(minutes) * 60 + float(seconds)
    if hours:
        seconds += float(hours[:-1]) * 60 * 60
    if millis:
        seconds += float(millis[1:]) / 10 ** len(millis[1:])
    if prefix == '-':
        seconds *= -1
    return seconds


def _normalize_timestr(timestr):
    timestr = _normalize(timestr)
    for specifier, time_unit_names in [('x', ['milliseconds', 'millisecond', 'millisecs', 'millisec',
                                              'millis', 'msecs', 'msec', 'ms']),
                                       ('s', ['seconds', 'second', 'secs', 'sec']),
                                       ('m', ['minutes', 'minute', 'mins', 'min']),
                                       ('h', ['hours', 'hour']),
                                       ('d', ['days', 'day'])]:
        for unit in time_unit_names:
            if unit in timestr:
                timestr = timestr.replace(unit, specifier)
    return timestr


def _normalize(string, ignore=(), caseless=True, spaceless=True):
    """
    Normalize given string according to given spec.

    By default string is turned to lower case and all whitespace is removed.
    Additional characters can be removed by giving them in `ignore` list.
    """
    if spaceless:
        string = _WHITESPACE_REGEXP.sub('', string)
    if caseless:
        string = string.lower()
        ignore = [i.lower() for i in ignore]
    for ign in ignore:
        if ign in string:  # performance optimization
            string = string.replace(ign, '')
    return string
